  const input=(label,name,value='',type='text',attrs='')=>`<label class="field"><span>${label}</span><input data-field="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
  const select=(label,name,items,value='')=>`<label class="field"><span>${label}</span><select data-field="${name}">${items.map(([v,n])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
  const options=values=>values.map(v=>[v,v]);
  const table=(rows)=>{const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];return `<div class="table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr>${keys.map(k=>`<td>${esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><small>${rows.length} Zeilen · Vorschau bis 100</small>`;};
  let disposed=false,dirty=false,info=null,object=null,worker=null,tab='data',nodeId=null,connect=null,busy=false,sequence=0,chartRows=[],pixel=Array(64).fill(0),refreshTimer,ragStep=0,analysisState={},disposeVectors=null,vectorRefreshTimer;
  const vectorViews=new Map();
  const params=new URLSearchParams(location.hash.split('?')[1]||'');tab=['data','model','quality','analysis'].includes(params.get('tab'))?params.get('tab'):'data';nodeId=params.get('node');ragStep=Math.max(0,Math.min(5,Number(params.get('step')||0)));try{const view=JSON.parse(params.get('analysis')||'{}');if(Object.values(view).every(v=>typeof v==='string'&&v.length<=120))analysisState=view;}catch{}const route=location.hash.slice(1).split('?')[0];let pid=params.get('project')||sessionStorage.getItem('entrosphere:lab-project:'+user.id)||'',requested=params.get('object');
  const kinds=(route==='graph'?['graph']:route==='data-lab'?['dataset']:['prompt','rag','network']).filter(k=>flags[FEATURE[k]]);
  const {projects}=await get('lab.projects');if(disposed)return()=>{};pid=projects.find(p=>p.id===pid)?.id||projects[0]?.id;
  root.innerHTML=`<div class="content lab-page"><div class="page-head"><div><div class="meta">PROJEKT // LERNWERKSTATT</div><h1>${route==='graph'?'Graph-Labor':route==='data-lab'?'Daten-Labor':'KI-Labor'}<span class="accent">.</span></h1><p>Ausprobieren. Zusammenhänge sehen.</p></div>${flags.editor?`<div class="toolbar">${flags.python||flags.php||flags.html?btn('Codebeispiel','code-example'):''}${btn('Zum Code','code')}</div>`:''}</div><div class="lab-project-bar">${select('Projekt','project',projects.map(p=>[p.id,p.name+(p.group_name?' · '+p.group_name:p.user_id!==user.id?' · '+(p.owner_name||'Teilnehmer'):'' )]),pid)}${['teacher','admin'].includes(user.role)?btn('Projekt einrichten','configure'):''}<span class="lab-status" role="status"></span></div><div class="lab-layout"><aside class="lab-sidebar"><label class="field"><span>Neu anlegen</span><select data-field="new-kind">${kinds.map(k=>`<option value="${k}">${LAB_LABELS[k]}</option>`).join('')}</select></label>${btn('Hinzufügen','new',true)}<nav class="lab-object-list" aria-label="Laborobjekte"></nav></aside><section class="lab-main"><div class="lab-object-toolbar"></div><div class="lab-error error" role="alert"></div><div class="lab-body"></div></section></div></div>`;
  if(!pid){$('.lab-body').innerHTML='<div class="empty"><h3>Zuerst ein Projekt anlegen</h3><p>Graphen und Experimente werden in Projekten gespeichert.</p><a class="es-btn es-btn--primary" href="#projects">Zu den Projekten</a></div>';return()=>{};}
  function changed(){dirty=true;setDirty(true);$('.lab-status').textContent='Ungespeichert';}
