    if(a==='import'){const file=document.createElement('input');file.type='file';file.accept='.json';file.onchange=async()=>{try{const f=file.files[0];if(!f)return;if(f.size>1048576)throw Error('Maximal 1 MB.');const v=JSON.parse(await f.text());if(v.kind&&v.kind!==object.kind)throw Error('Dieser Import gehört zu einem anderen Labor.');const validated=await api('lab.validate',{project:pid,kind:object.kind,content:v.content||v});object.content=validated.content;changed();draw();}catch(e){fail(e);}};file.click();return;}
