    if(a.startsWith('type:delete:')){const i=Number(a.split(':')[2]);if(g.nodes.some(n=>n.type===g.types[i].name))throw Error('Dieser Typ wird noch von Knoten verwendet.');g.types.splice(i,1);changed();draw();return;}
